private object PhilosophiaData {
    val questions = listOf(
        LifeQuestion("What makes a life meaningful?", "Meaning may not be something you discover. It may be something you build through what you choose to care about.", listOf(
                Perspective("Existentialism", "Existentialism, associated with Kierkegaard, Sartre, and de Beauvoir, begins with the premise that life has no pre-assigned meaning. Humans are “condemned to be free,” thrust into existence without a cosmic script, yet burdened with the responsibility to create their own purpose. A meaningful life emerges when one confronts this radical freedom with honesty, refusing to evade it through self-deception or reliance on false certainties. Sartre identifies authenticity as central: to live authentically is to accept life’s absurdity, make deliberate choices, and own both their consequences and limitations. Existentialists argue that meaning is not found waiting in the universe; it is forged in personal acts of commitment, love, creativity, and moral decision. Even in the face of despair or uncertainty, individuals can affirm life by asserting their values and defining themselves through action. This philosophy inspires courage, as it demands a life where one continuously reflects, chooses, and lives deliberately, transforming the apparent void into a field for self-realisation."),
                Perspective("Stoicism", " Stoicism, an influential Hellenistic philosophy founded by Zeno of Citium, asserts that a meaningful life arises from living according to reason and in harmony with nature. Stoics hold that external circumstances—wealth, status, or health—are ultimately indifferent because they lie outside our full control. Instead, life’s real value is measured by the cultivation of inner virtues: wisdom, courage, justice, and temperance. These virtues guide one to act rightly regardless of fortune. Suffering, according to the Stoics, emerges from trying to control the uncontrollable, such as the actions of others or the whims of fate. The practice of amor fati, or loving one’s fate, encourages acceptance of life’s events without resistance. By focusing exclusively on self-mastery and moral integrity, an individual achieves tranquillity and resilience. The Stoics also see meaning in fulfilling social duties and contributing to the rational order of the cosmos. Ultimately, a meaningful life is one where the individual lives in alignment with reason, maintains equanimity in adversity, and recognises that true freedom lies in the mastery of one’s mind and choices, not in conquest over external conditions."),
                Perspective("Epicureanism", "Epicureanism, founded by Epicurus in the 3rd century BCE, proposes that the essence of a meaningful life lies in the pursuit of pleasure understood as lasting tranquillity rather than indulgent excess. True happiness is achieved through ataraxia—a serene mind free from fear—and aponia—the absence of bodily pain. Epicurus taught that natural and necessary pleasures, such as simple food, shelter, and friendship, are the foundation of contentment. In contrast, unnecessary or vain desires, like the relentless chase for wealth or fame, lead to anxiety and suffering. By moderating desires and focusing on the present, one can cultivate a state of peaceful satisfaction. Epicureanism also addresses the fear of death, asserting that death is merely the cessation of consciousness and thus not to be feared. A meaningful life, therefore, is one that embraces modest pleasures, nurtures deep relationships, appreciates the simple joys of existence, and lives free from unnecessary distress and superstition. In finding harmony between the body’s needs and the mind’s clarity, Epicureanism offers a vision of meaning anchored in quiet fulfilment and gratitude for life’s fleeting yet genuine delights."),
                Perspective("Utilitarianism", "Utilitarianism, articulated by Jeremy Bentham and John Stuart Mill, grounds the meaning of life in the moral imperative to maximise overall happiness. Life is most meaningful when devoted to actions that promote the greatest good for the greatest number, balancing pleasure and the minimisation of suffering. This philosophy evaluates choices by their consequences, encouraging individuals to consider the ripple effects of their behaviour on society and the well-being of others. Mill refined Bentham’s approach by distinguishing between higher and lower pleasures, arguing that intellectual, moral, and cultural joys offer a more profound and lasting fulfilment than fleeting physical gratifications. A life directed toward alleviating suffering, advancing education, fostering justice, and contributing to collective prosperity reflects utilitarian values. In this framework, meaning is not only personal but also fundamentally social, as purpose arises from service to humanity. By engaging in acts that improve lives and expand happiness, individuals participate in a moral project that transcends themselves, creating a legacy of positive impact and harmonising personal satisfaction with universal welfare."),
                Perspective("Nihilism", "Nihilism, often linked to Friedrich Nietzsche, asserts that life has no inherent meaning, value, or purpose. Traditional sources of significance—religion, morality, or divine order—are, from this perspective, human constructions without objective grounding. At first glance, this worldview can produce despair, as the universe appears indifferent and human efforts seem ultimately futile. Pure nihilism might lead to apathy, disconnection, or even self-destruction, as it dismantles the comforting narratives that guide most lives. Yet, Nietzsche also saw a potential liberation in confronting the void. By recognising the absence of pre-given meaning, an individual is freed to create personal values and define life on their own terms. His concept of the Übermensch embodies this creative response, transforming the collapse of old certainties into an opportunity for self-overcoming and purposeful living. Within nihilism, meaning is not discovered but invented, demanding intense courage and self-responsibility. A life becomes meaningful only when one dares to face the abyss honestly and respond with self-authored purpose, turning nothingness into a canvas for personal expression."),
                Perspective("Absurdism", "Absurdism, championed by Albert Camus, explores the tension between humanity’s deep longing for meaning and the universe’s silence. Life appears absurd because it offers no ultimate answers, yet humans are compelled to seek them anyway. Camus argues that attempting to escape this absurdity through faith or denial only avoids the truth; instead, one must confront it directly. A meaningful life arises not from resolving the absurd but from embracing it with defiance and vitality. Camus’s metaphor of Sisyphus—forever pushing his boulder uphill—captures this attitude: though the task is futile, Sisyphus is imagined as happy because he accepts the struggle and finds joy in the act itself. Meaning is created by fully living in the present, engaging in acts of love, creativity, and rebellion against life’s inherent emptiness. Absurdism encourages a bold embrace of existence without illusion, discovering value not in cosmic purpose but in the sheer experience of living and affirming life despite its ultimate ambiguity."),
                Perspective("Virtue Ethics", "Virtue ethics, rooted in Aristotle’s philosophy, sees a meaningful life as one of eudaimonia, or flourishing, achieved through the cultivation of moral and intellectual virtues. Unlike rule-based or outcome-focused moralities, virtue ethics emphasises character formation and the development of good habits. Meaning arises from living in accordance with one’s potential, guided by virtues such as courage, justice, honesty, and compassion. These qualities help navigate life’s challenges while fostering harmonious relationships and social contribution. Aristotle also emphasised the importance of finding a balance, or the “golden mean,” between extremes in behaviour. A flourishing life is one embedded in community, where personal growth aligns with the broader good. By committing to lifelong self-improvement, nurturing friendships, and fulfilling one’s responsibilities, an individual lives not just successfully but meaningfully. In this view, the good life is neither about fleeting pleasures nor rigid moral codes but about the holistic development of character, enabling one to thrive in personal, social, and ethical dimensions."),
                Perspective("Buddhism", "Buddhism frames a meaningful life as one that moves towards liberation from suffering, or nirvana, by realising the impermanent and selfless nature of existence. Central to this understanding is the recognition of dukkha, the pervasive dissatisfaction inherent in life, which arises from craving, attachment, and ignorance. Meaning is cultivated through the Noble Eightfold Path, which integrates ethical conduct, mental discipline, and wisdom: right understanding, intention, speech, action, livelihood, effort, mindfulness, and concentration. By practising mindfulness and meditation, one learns to see reality clearly, gradually loosening the grip of ego-driven desires. Compassion for all living beings is essential, as reducing others’ suffering contributes to inner peace. Fear of death diminishes when one accepts impermanence and the cycle of samsara with equanimity. Rather than seeking meaning in external accomplishments, Buddhism points inward, where liberation unfolds through insight, ethical living, and serenity. A meaningful life, therefore, is one of awakening, where the mind becomes free from delusion and attains profound, enduring peace. .")
        )),
        LifeQuestion("What is happiness?", "Is happiness a feeling, a peaceful life, or something deeper than simply feeling good?", listOf(
                Perspective("Existentialism", "Existentialism views happiness as a deeply personal and subjective experience, arising from the individual’s confrontation with freedom and responsibility. Life is inherently without prescribed meaning, and each person must create purpose through authentic choices. For an existentialist, happiness does not come from external validation or social norms but from living truthfully according to one’s own self-defined values. This can involve embracing anxiety, uncertainty, and even despair as integral aspects of existence. When an individual accepts the absurdity of life and takes ownership of their choices, they achieve a form of inner liberation. Happiness, in this perspective, is not constant joy but the fulfilment of living authentically and courageously in the face of life’s inherent uncertainty."),
                Perspective("Stoicism", "Happiness, according to Stoicism, is achieved through the cultivation of inner virtue and the acceptance of the natural order of life. A Stoic believes that external events are beyond our control, and thus our emotional well-being should not depend upon them. True happiness comes from mastering one’s desires, understanding the limits of control, and harmonising with reason. By practising self-discipline and focusing on personal moral integrity, one achieves tranquillity—or “ataraxia.” Challenges and hardships are seen as opportunities to strengthen character rather than to lament. For the Stoic, happiness is not a fleeting feeling but a stable state of equanimity rooted in wisdom and virtue. It is found not in pleasure or possessions but in living a virtuous life aligned with nature and reason."),
                Perspective("Epicureanism", " Epicureanism defines happiness as the pursuit of pleasure and the avoidance of pain, but in a measured and intelligent manner. Epicurus distinguished between fleeting physical pleasures and the deeper, sustainable pleasures of a tranquil life. He believed happiness is not indulgence in excess but the cultivation of simple joys, the absence of bodily pain (aponia), and mental serenity (ataraxia). Friendships, reflective thought, and freedom from fear—especially the fear of death—are central to achieving happiness. For Epicureans, understanding the nature of the world through rational thought eliminates unnecessary anxieties, particularly those stemming from superstition or fear of divine punishment. Ultimately, happiness is found in modest living, intellectual satisfaction, and the appreciation of life’s small, certain pleasures over the pursuit of grand, uncertain ambitions."),
                Perspective("Utilitarianism", " Utilitarianism approaches happiness as a collective experience, defining it as the greatest good for the greatest number of people. Actions are morally right if they maximise overall well-being and minimise suffering. For the utilitarian, personal happiness is interconnected with the welfare of others, and ethical decisions are evaluated in terms of their consequences. Happiness is seen as measurable in terms of pleasure and pain, though higher intellectual and moral pleasures are valued above purely physical ones. A utilitarian life aims to balance personal satisfaction with social responsibility, creating a world where happiness is distributed as widely as possible. Decisions, therefore, are not merely personal but moral calculations of how to increase joy and reduce harm for society at large. This perspective frames happiness as a shared, practical, and ethical outcome rather than a purely individual pursuit."),
                Perspective("Nihilism", "Nihilism challenges the notion of happiness by denying any inherent meaning or value in life. From a nihilistic standpoint, the pursuit of happiness is ultimately arbitrary, as life possesses no objective purpose or moral framework. Attempts to attach grand significance to human existence are seen as illusions. For a nihilist, happiness may either be dismissed as irrelevant or redefined as a personal indulgence without universal significance. This perspective can lead to despair, but some nihilists embrace a sense of liberation in recognising life’s emptiness, freeing themselves from imposed societal or religious expectations. Happiness, if it exists in nihilism, comes from self-created moments of satisfaction, detached from any larger metaphysical justification. It is a fleeting, subjective experience, acknowledged without illusion."),
                Perspective("Absurdism", "Absurdism, as articulated by Albert Camus, recognises the human desire for meaning in a universe that offers none. The conflict between this desire and the world’s indifference is the “absurd.” For the absurdist, happiness arises not from resolving this tension but from embracing it. By accepting life’s lack of ultimate purpose, one can live fully and freely, finding joy in the experience itself rather than in searching for transcendent validation. Camus suggested that acknowledging the absurd allows for a defiance that breeds happiness—the act of living passionately despite meaninglessness. Happiness is therefore a form of rebellion, a conscious choice to engage with life, create personal significance, and savour the simple beauty of existence, even when it is inherently absurd."),
                Perspective("Virtue Ethics", "Virtue ethics, most famously developed by Aristotle, associates happiness (or eudaimonia) with the flourishing of human potential through the cultivation of moral and intellectual virtues. Happiness is not merely a feeling but a state of living well and fulfilling one’s unique purpose. This requires practising virtues such as courage, temperance, justice, and wisdom, which align one’s character with the rational order of life. Virtue ethicists believe that happiness is achieved over a lifetime of virtuous action, rather than through momentary pleasures or external rewards. It is an active process of becoming one’s best self and contributing positively to the community. In this perspective, happiness is the natural outcome of a life of moral excellence and self-realisation, harmonising personal fulfilment with social good.."),
                Perspective("Buddhism", " Buddhism offers a profound understanding of happiness, viewing it as an inner state of being rather than something that can be permanently obtained through external means. At the heart of Buddhist philosophy is the recognition that life involves suffering, or dukkha, which arises from desire, attachment, and ignorance. People often chase after fleeting pleasures, believing that the fulfilment of desires will bring happiness. However, Buddhism teaches that such satisfaction is temporary, and true happiness emerges when one liberates the mind from constant craving and aversion. Central to this teaching are the Four Noble Truths, which form the foundation of Buddhist thought. The first truth states that suffering is an inherent part of life, experienced as dissatisfaction, stress, or pain. The second truth identifies the cause of suffering as desire and attachment, the relentless pursuit of things we believe will make us happy. The third truth brings hope, asserting that suffering can indeed be overcome by letting go of these attachments. The fourth truth provides guidance, pointing to the Noble Eightfold Path as the way to end suffering and achieve a state of peace and joy.The Noble Eightfold Path is a practical guide to living a life of balance and ethical discipline. It is divided into three main aspects: wisdom, ethical conduct, and mental discipline. Wisdom involves right understanding and right intention, which help individuals see life clearly and act with compassion. Ethical conduct includes right speech, right action, and right livelihood, creating harmony with oneself and others. Mental discipline is developed through right effort, right mindfulness, and right concentration, which cultivate a calm and focused mind. By diligently practising these steps, a person gradually transforms their mind, freeing it from greed, hatred, and delusion., perspectives on “What is Happiness?.")
        )),
        LifeQuestion("Do we have free will?", "If your choices are influenced by your biology, experiences, and environment, how free are they?", listOf(
                Perspective("Stoicism", " Stoicism presents a profound view of free will grounded in its understanding of a universe governed by rational order, often referred to as the Logos. For the Stoics, everything external unfolds according to this universal reason, which is deterministic in nature. Human beings, however, hold a special position because they possess the capacity for rational thought. This rationality allows individuals to align their inner will with the natural order, even if they cannot alter the events around them. According to Stoicism, true freedom does not come from controlling external circumstances, which are ultimately beyond our grasp, but from mastering our judgments and responses. When a calamity strikes or fortune turns, our moral freedom is exercised in choosing whether to respond with anger, despair, or with calm acceptance and virtue. By practising the Stoic discipline of desire, aversion, and assent, one learns to distinguish what is within one’s power—thoughts, intentions, and actions—from what is not. In this way, Stoics redefine free will as inner freedom, a state where the mind remains unshaken by fate. To live in harmony with reason and nature is to achieve a deeply liberating form of autonomy, no matter how deterministic the outer world may appear."),
                Perspective("Existentialism", "Whatever our circumstances, we remain responsible for how we respond to them. Existentialism, and especially the philosophy of Jean-Paul Sartre, positions human freedom at the very heart of existence. For Sartre, “existence precedes essence,” meaning that human beings are not born with a predetermined purpose or nature; instead, they must create themselves through their choices. This radical freedom is both empowering and burdensome, for it leaves no room to hide behind excuses such as fate, societal norms, or psychological conditioning. Sartre famously wrote that we are “condemned to be free,” because even in situations of extreme pressure or limitation, we still bear responsibility for the choices we make—including the choice to do nothing. Free will in this framework is not a distant metaphysical concern but a lived experience that defines authenticity. To act authentically is to embrace one’s freedom, confront the absurdity of life, and acknowledge that meaning arises only from the commitments we freely undertake. Existentialism thus ties free will to moral responsibility, as every decision shapes not only one’s own life but also expresses a vision of humanity itself. In facing the world without inherent meaning, existentialists find liberation in the courage to choose and in the refusal to surrender to passive determinism."),
                Perspective("Epicureanism", "Epicureanism offers a distinctive approach to free will, connecting it to its materialist understanding of the universe. According to Epicurus, the world is composed of indestructible atoms moving through the void, and their interactions create all phenomena, including human life. While this might suggest a strictly deterministic system, Epicurus introduced the concept of the “swerve” (clinamen), a spontaneous and unpredictable deviation in the motion of atoms. This swerve breaks the rigid chain of causality and opens a space for human agency and freedom. For the Epicureans, the value of free will is not in abstract speculation but in its practical contribution to the good life. Their philosophy advocates for ataraxia—peace of mind—achieved through the pursuit of simple pleasures, avoidance of unnecessary pain, and the cultivation of friendship and wisdom. Free will enables individuals to make reasoned choices that steer them away from destructive desires or irrational fears, such as fear of the gods or of death. In this sense, free will is the foundation for living a tranquil, self-sufficient, and pleasurable life. It is not the freedom to control every outcome, but the ability to align one’s choices with the natural pursuit of happiness."),
                Perspective("Utilitarianism", "Utilitarianism approaches free will from a pragmatic rather than metaphysical standpoint. Rooted in the moral philosophy of thinkers like Jeremy Bentham and John Stuart Mill, utilitarianism is focused on the outcomes of actions and the maximisation of overall happiness or utility. While it does not engage deeply in questioning whether free will exists in a deterministic universe, it operates on the practical assumption that human beings are capable of assessing consequences and making meaningful choices. Individuals are seen as agents who can weigh potential benefits and harms, then act in ways that produce the greatest good for the greatest number. This implicit reliance on free will underpins ethical decision-making in utilitarian thought. Even if determinism were true, utilitarianism would still function effectively because it is concerned with influencing behaviour through reasoning, education, and social incentives. Free will, in this framework, is less about metaphysical independence and more about the capacity to deliberate and act in ways that enhance collective well-being. Ultimately, what matters is that people can respond to moral reasoning, make calculated decisions, and contribute to a society where happiness is maximised and suffering is minimised."),
                Perspective("Nihilism", "Nihilism offers a bleak perspective on the question of free will. It posits that life lacks inherent meaning or purpose, and as a result, human actions are ultimately devoid of objective significance. In the context of free will, nihilists might argue that our sense of choice is an illusion, conditioned by forces beyond our control such as biology, environment, and social structures. If there is no ultimate meaning, then the concept of choosing one path over another holds little weight, because all outcomes are equally void of cosmic importance. This perspective can lead one to question whether free will truly exists or if it is a comforting construct to endure life’s emptiness. Yet, some nihilists might embrace a form of liberated acceptance, acting authentically in the face of meaninglessness, even if free will is ultimately constrained by determinism."),
                Perspective("Absurdism", "Absurdism, closely associated with the philosophy of Albert Camus, addresses the tension between humanity’s search for meaning and the universe’s apparent indifference. When considering free will, the absurdist approach suggests that, while life may lack inherent purpose, individuals are still free to define their own meaning. Free will manifests in our ability to confront the absurd and make choices despite the lack of a grand design. Camus’ idea of rebellion against the absurd illustrates that even in a purposeless cosmos, our conscious decisions matter to us, if not to the universe. The recognition that no external force dictates the ultimate significance of our actions can empower individuals to live authentically. Therefore, while the absurd acknowledges deterministic elements of existence, it celebrates the personal freedom to choose how one engages with life’s inherent absurdity."),
                Perspective("Virtue Ethics", "Virtue ethics, rooted in the teachings of Aristotle, approaches free will through the lens of moral character and the cultivation of virtues. Aristotle suggests that a good life arises from the habitual practice of virtues such as courage, temperance, and wisdom. With regard to free will, virtue ethics assumes that individuals are capable of making choices that reflect their character and moral reasoning. While external circumstances and upbringing influence behaviour, virtue is developed through conscious effort and repeated action, implying that free will is exercised in the pursuit of moral excellence. According to this view, free will is not absolute independence from causality but the capacity to act in accordance with one’s rational nature and ethical understanding. In this way, virtue ethics frames free will as a practical, lived experience, where our freedom is realised through deliberate choices that shape our character and contribute to a flourishing life."),
                Perspective("Buddhism", "Buddhism presents a nuanced perspective on free will, intertwined with its doctrines of karma and dependent origination. It recognises that human beings are conditioned by past actions, desires, and attachments, which can limit the scope of their choices. However, Buddhism also emphasises the potential for liberation through mindfulness and wisdom. In this framework, free will exists as the capacity to cultivate awareness and break free from cycles of craving and suffering. By practising meditation and ethical conduct, individuals can gradually loosen the grip of conditioning and exercise a form of enlightened choice. Rather than viewing free will as unrestricted autonomy, Buddhism frames it as the ability to transcend habitual patterns and act with compassion and clarity. This perspective suggests that true freedom arises not from asserting control over every circumstance but from understanding the impermanent and interdependent nature of existence, thus aligning one’s actions with the path to enlightenment.")
        )),
        LifeQuestion("What makes someone a good person?", "Is morality about rules, consequences, intentions, or the kind of person you become?", listOf(
                Perspective("Stoicism", "From the perspective of Buddhism, a “good person” is one who embodies compassion, wisdom, and mindfulness in daily life. Central to Buddhist teachings is the understanding that our actions, thoughts, and intentions shape our karma, and thus, a truly good person is conscious of the impact they have on others and the world around them. A good person, according to Buddhism, practises the Five Precepts: refraining from harming living beings, stealing, engaging in sexual misconduct, speaking falsely, and consuming intoxicants that cloud the mind. By following these, one cultivates moral discipline and avoids causing suffering. However, being good is not simply about adhering to rules; it is about developing a heart of loving-kindness (metta) and compassion (karuna) toward all beings without discrimination."),
                Perspective("Existentialism", "Existentialist philosophy, rooted in thinkers like Jean-Paul Sartre and Søren Kierkegaard, views a good person as someone who embraces authentic existence. Existentialism emphasises the individual’s freedom and responsibility to create their own values in a world that may lack inherent meaning. To be good is not to follow pre-set moral codes blindly; rather, it is to take ownership of one’s choices and live in alignment with self-defined principles. A good person accepts the anxiety and weight of freedom, acknowledging that they are fully accountable for their actions and their impact on others. Kierkegaard highlighted the importance of personal faith and commitment, while Sartre focused on authenticity and avoiding “bad faith,” which is self-deception or conformity to external expectations. For an existentialist, morality is deeply personal yet intertwined with others, as one’s freedom coexists with the responsibility not to harm or diminish the freedom of others. A good person acts with awareness, honesty, and courage in the face of life’s absurdity. By fully embracing freedom, making deliberate choices, and accepting the consequences, an individual lives authentically and earns the existentialist sense of being a good person.."),
                Perspective("Epicureanism", "Existentialist philosophy, rooted in thinkers like Jean-Paul Sartre and Søren Kierkegaard, views a good person as someone who embraces authentic existence. Existentialism emphasises the individual’s freedom and responsibility to create their own values in a world that may lack inherent meaning. To be good is not to follow pre-set moral codes blindly; rather, it is to take ownership of one’s choices and live in alignment with self-defined principles. A good person accepts the anxiety and weight of freedom, acknowledging that they are fully accountable for their actions and their impact on others. Kierkegaard highlighted the importance of personal faith and commitment, while Sartre focused on authenticity and avoiding “bad faith,” which is self-deception or conformity to external expectations. For an existentialist, morality is deeply personal yet intertwined with others, as one’s freedom coexists with the responsibility not to harm or diminish the freedom of others. A good person acts with awareness, honesty, and courage in the face of life’s absurdity. By fully embracing freedom, making deliberate choices, and accepting the consequences, an individual lives authentically and earns the existentialist sense of being a good person.."),
                Perspective("Utilitarianism", "Utilitarianism defines a good person as one who acts to maximise overall happiness and minimise suffering. Developed by Jeremy Bentham and expanded by John Stuart Mill, this ethical framework evaluates morality based on the consequences of actions, not intentions. A good person considers the well-being of all affected parties, striving to produce the greatest good for the greatest number. Self-interest is not ignored but is balanced against the interests of society as a whole. In daily life, a utilitarian good person makes choices that promote collective welfare, such as helping those in need, supporting fair policies, and avoiding actions that cause harm or unnecessary pain. Goodness is practical and results-oriented, grounded in empathy and rational calculation of outcomes. The moral worth of any action is judged by its utility—how much happiness or reduction of suffering it provides. Being a good person in this context requires awareness, impartiality, and the willingness to sometimes sacrifice personal gain for the benefit of others. By prioritising the overall balance of pleasure over pain, a utilitarian good person contributes to a more compassionate, fair, and prosperous society."),
                Perspective("Nihilism", "Nihilism, particularly moral nihilism, challenges the very concept of a good person by asserting that objective moral values do not exist. In its purest form, nihilism claims that concepts of good and evil are human constructs without universal grounding. From this perspective, there is no absolute standard by which to measure a person as “good.” However, an individual might still choose to define goodness subjectively or pragmatically, creating their own meaning in life. A nihilistic approach might lead someone to reject traditional moral duties, viewing them as arbitrary, yet they may still act kindly or ethically out of personal preference, social conditioning, or the desire for harmony. In this sense, the idea of a good person is fluid, dependent on personal or cultural interpretations. Some nihilists, influenced by thinkers like Friedrich Nietzsche, see an opportunity in this freedom, encouraging individuals to create their own values and live authentically beyond imposed moral frameworks. While nihilism does not prescribe a clear path to goodness, it invites reflection on whether goodness is an external standard or a personal construct. In practice, a “good” nihilist is one who consciously chooses their actions without illusions of inherent moral truth."),
                Perspective("Absurdism", "Absurdism, as articulated by Albert Camus, views the question of what makes a good person through the lens of life’s inherent absurdity. Human beings naturally seek meaning, yet the universe offers none, creating the “absurd.” A good person in this philosophy is one who acknowledges this condition without resorting to despair or false consolations. Rather than seeking ultimate moral rules or cosmic approval, the absurdist embraces life fully and authentically, creating personal meaning through actions, relationships, and experiences. A good person accepts the freedom and responsibility that arise from a meaningless universe and lives with integrity, joy, and compassion despite the lack of inherent purpose. Camus’ metaphor of Sisyphus illustrates that the good life involves embracing the struggle itself, finding happiness in honest engagement with existence. In practice, this could mean acting kindly, pursuing passions, and supporting others, not because it is objectively required, but because it enriches life. For the absurdist, a good person is one who lives without self-deception, resists nihilistic paralysis, and courageously creates meaning in a silent world, embodying defiance and generosity in the face of the absurd.."),
                Perspective("Virtue Ethics", "Virtue ethics, rooted in Aristotle’s philosophy, defines a good person as someone who develops moral character through the cultivation of virtues. Unlike rule-based or consequence-focused systems, virtue ethics emphasises the formation of good habits and the pursuit of eudaimonia—human flourishing or the good life. A good person is not simply one who performs isolated good acts but one whose character consistently reflects virtues such as courage, honesty, generosity, and temperance. Moral education, practice, and community play essential roles in shaping one’s character. Virtue ethics also acknowledges the importance of practical wisdom (phronesis), the ability to discern how to act virtuously in different situations. A good person strikes a balance between extremes, embodying the “Golden Mean,” where virtues lie between deficiencies and excesses. For example, courage is the mean between cowardice and recklessness. In everyday life, the good person pursues actions that nurture both personal well-being and the flourishing of society, guided by a deep sense of moral purpose. By continuously cultivating virtues and living in accordance with reasoned moral judgement, an individual becomes a good person in the fullest sense, harmonising personal growth with ethical responsibility.")
        )),
        LifeQuestion("Should you care what others think?", "Other people's opinions can matter, but should they determine your sense of worth?", listOf(
                Perspective("Stoicism", "Stoicism teaches that external opinions are beyond our control and thus should not disturb our inner peace. A Stoic would argue that what others think of you is merely a reflection of their own perceptions and judgments. True tranquillity comes from aligning your actions with reason and virtue, not from chasing approval. If you care excessively about others’ thoughts, you hand over your emotional state to forces outside your control. Marcus Aurelius advised focusing on your own moral character and letting go of the noise of public opinion. From this lens, caring about others’ opinions only to the extent that it helps you act justly and responsibly is acceptable, but anxiously seeking validation is a form of enslavement to externalities. The Stoic practices detachment, reminding themselves that fame or shame is fleeting, and that personal integrity is the only true measure of value. In the end, a Stoic would suggest that you should acknowledge others’ views but never allow them to dictate your peace of mind. Cultivating an unshakable inner citadel, where reason and virtue guide your life, makes external approval unnecessary and largely irrelevant to your happiness."),
                Perspective("Existentialism", " Existentialism emphasises individual freedom, authenticity, and the responsibility to define one’s own meaning. From this perspective, whether you should care about others’ opinions depends entirely on whether doing so aligns with your authentic self. Jean-Paul Sartre argued that humans live in a “state of being-for-others,” constantly observed and judged, yet true authenticity requires owning one’s choices rather than conforming to societal expectations. If you live in fear of others’ opinions, you risk living in “bad faith,” surrendering your freedom and avoiding the weight of self-definition. Existentialism does not deny that others’ thoughts affect our lives, but it challenges you to confront that influence consciously. You may choose to consider others’ perspectives as part of your lived experience, but ultimately, your life’s meaning cannot be outsourced to their approval. In this view, caring about others’ opinions is not inherently wrong, but it must never override your personal responsibility to live authentically. To be true to yourself, you must sometimes accept isolation, criticism, or misunderstanding as the price of genuine freedom."),
                Perspective("Epicurean", "Epicureanism is often misunderstood as hedonistic indulgence, yet its core philosophy is the pursuit of long-term tranquillity through moderation and the avoidance of pain. Epicurus would suggest that caring excessively about others’ opinions disrupts inner peace and generates unnecessary anxiety. Gossip, social competition, and the fear of judgement are sources of mental disturbance that should be minimised. However, Epicureanism also acknowledges that some social harmony contributes to a pleasurable life. Completely disregarding others’ views may invite conflict or isolation, which can lead to discomfort. Thus, the Epicurean approach is pragmatic: consider others’ opinions only insofar as it helps maintain peaceful relationships and avoid trouble, but never let them dominate your mind. The wise person surrounds themselves with trusted friends whose opinions are rooted in mutual care, and largely ignores the superficial judgments of the wider world. By cultivating simple pleasures, self-sufficiency, and secure friendships, you reduce the emotional weight of public perception. For Epicureans, the best life is one where your happiness depends on your own inner contentment, not on the shifting and unreliable opinions of society."),
                Perspective("Utilitarianism", "Utilitarianism evaluates actions by their consequences, aiming to maximise overall happiness and minimise suffering. In this framework, whether you should care about others’ opinions depends on the effects those opinions have on the collective well-being. If ignoring public sentiment causes harm, social discord, or diminishes happiness for yourself or others, then it becomes morally significant to consider what people think. For example, public trust can influence cooperation and the smooth functioning of society. However, Utilitarianism does not insist that you seek approval for its own sake; rather, it treats social perception as a factor in the calculus of consequences. If caring about others’ opinions leads to actions that increase general happiness—such as fostering harmony, preventing misunderstandings, or encouraging positive behaviour—then it is justified. Conversely, if constantly worrying about what others think diminishes your mental health without improving overall utility, it is not a moral requirement. In this view, the decision is practical and context-dependent, weighing the outcomes for everyone involved rather than binding you to social norms or personal detachment."),
                Perspective("Nihilism", "Nihilism asserts that life has no inherent meaning, purpose, or objective values. From a Nihilistic perspective, the question of whether to care about others’ opinions becomes largely irrelevant, since neither approval nor disapproval carries ultimate significance. Moral codes, social expectations, and judgments are human constructs without universal grounding. A Nihilist might conclude that caring about others’ opinions is an arbitrary choice with no intrinsic value; the universe is indifferent, and therefore the weight we assign to reputation or judgment is self-imposed. However, practical considerations still exist in daily life. You might choose to acknowledge others’ views to avoid trouble or to achieve certain personal goals, but such choices are not tied to any higher moral imperative. In a fully Nihilistic frame, someone could ignore society completely or conform for convenience, knowing that both paths are equally meaningless in the cosmic sense. Thus, caring or not caring becomes a personal preference rather than an ethical principle. Freedom in Nihilism lies in realising that the pressure to seek validation is ultimately an illusion."),
                Perspective("Absurdism", "Absurdism, as articulated by Albert Camus, recognises the tension between humanity’s search for meaning and the universe’s indifference. In the context of caring about others’ opinions, the Absurdist would see both the desire for approval and the futility of that desire as part of the human condition. People naturally want to be understood and accepted, yet this craving often collides with the realisation that others’ views are fleeting, inconsistent, and ultimately incapable of granting permanent significance. Camus suggests that rather than escaping this absurdity through denial or submission, one should embrace it. Caring about others’ opinions becomes a conscious choice rather than an automatic compulsion. You can acknowledge that seeking approval is part of the shared human experience, but also laugh at its ultimate absurdity. In practice, an Absurdist may balance caring enough to engage meaningfully with society, while maintaining inner freedom through detachment from final validation. By living fully in the face of the Absurd, you can care when it matters to you, without expecting ultimate resolution or cosmic justification."),
                Perspective("Virtue Ethics", " Virtue Ethics, rooted in Aristotle, focuses on cultivating good character and living a flourishing life (eudaimonia). From this perspective, caring about others’ opinions has moral relevance if it relates to the development of virtue. Public opinion can serve as a mirror, reflecting whether your actions embody qualities like courage, honesty, and justice. A virtuous person considers others’ views not to seek shallow praise, but to receive feedback on whether they are living in harmony with moral excellence. However, excessive dependence on external validation indicates a deficiency in self-sufficiency and practical wisdom (phronesis). The ideal approach is measured: you listen to the wise and trusted members of your community, using their opinions as guidance for growth, while disregarding the fickle or ignorant judgments of the crowd. In pursuing virtue, your ultimate goal is internal moral harmony, not popularity. Thus, you should care about what others think only insofar as it helps refine your character and supports a life of meaningful ethical action, not as an end in itself.."),
                Perspective("Buddhism", "Buddhism approaches the question of caring about others’ opinions through the lens of impermanence, non-attachment, and the cessation of suffering. In Buddhist thought, craving for approval and aversion to criticism are forms of tanhā (desire) that bind us to dukkha (suffering). Opinions, like all phenomena, are transient and conditioned by the perceptions, karma, and ignorance of others. To overly identify with praise or blame is to reinforce the ego, which Buddhism teaches is ultimately illusory. Therefore, clinging to others’ validation disrupts inner peace and hinders the path to enlightenment.")
        )),
        LifeQuestion("Why do we suffer?", "Suffering is part of human life, but what we do with it can change its meaning.", listOf(
                Perspective("Stoicism", " Stoicism teaches that suffering arises not from external events but from our judgments about them. According to Stoic philosophy, the world operates under divine reason (Logos), and much of what happens is beyond our control. When we attach our peace of mind to external circumstances, we invite suffering. True freedom lies in recognising what is within our power—our thoughts and actions—and accepting what is not. Suffering diminishes when we cultivate virtues like wisdom, courage, justice, and temperance, and align our will with nature. Stoics recommend practices such as negative visualisation and reflection on mortality to train the mind to remain tranquil amid life’s hardships. In this way, suffering becomes a teacher, showing us where we are clinging to illusions of control, and through acceptance and rational perspective, we achieve inner equanimity."),
                Perspective("Existentialism", "Existentialists like Jean-Paul Sartre and Albert Camus view suffering as inherent to the human condition because existence precedes essence. We are thrust into a world without predetermined meaning and must create our own purpose in the face of absurdity and freedom. The awareness of mortality, isolation, and the burden of choice produces existential angst, which is a form of suffering. However, this suffering is also an opportunity for authenticity. By acknowledging the absurd and embracing our freedom to define ourselves, we can transform suffering into a means of self-creation. Existentialism does not offer escape from suffering but encourages facing it honestly, without relying on external systems of meaning, and living fully despite it.."),
                Perspective("Epicureanism", "Epicureanism teaches that suffering arises mainly from fear—fear of death, of divine punishment, and of unfulfilled desires. Epicurus argued that pleasure, understood as the absence of pain and mental disturbance (ataraxia), is the highest good. By understanding the natural limits of desires, we can reduce unnecessary suffering caused by craving or ambition. Physical pain is usually short-lived, while mental suffering often stems from irrational beliefs about the gods or the afterlife. Through rational examination of nature, we learn that death is simply the end of sensation and not to be feared. Friendship, simple living, and the pursuit of modest pleasures allow one to minimise suffering and live a tranquil life. Thus, suffering is lessened by cultivating knowledge, moderation, and freedom from superstitions."),
                Perspective("Utilitarianism", "Utilitarianism approaches suffering from a moral and practical perspective: suffering is a negative utility, a decrease in overall happiness or well-being. Jeremy Bentham and John Stuart Mill argue that the moral imperative is to act in ways that minimise suffering and maximise happiness for the greatest number. Suffering occurs due to harmful actions, social injustice, natural pain, and unmet needs. It can be mitigated through ethical decision-making, social reforms, and the application of reason to improve individual and collective conditions. While suffering is an inevitable part of life, its moral significance lies in our responsibility to reduce it wherever possible. Under utilitarian logic, understanding the sources of suffering provides a framework for creating policies and behaviours that systematically alleviate pain and increase flourishing."),
                Perspective("Absurdism", "Absurdism, associated with Albert Camus, sees suffering as an inevitable result of the confrontation between human desire for meaning and the indifferent universe that offers none. This tension is the absurd. Attempts to escape it through illusions—religion, false certainty, or denial—only postpone the encounter with suffering. Camus suggests that rather than seeking to eliminate the absurd, we must embrace it, acknowledging life without ultimate meaning while still choosing to live fully. Suffering, in this view, is a by-product of our awareness and our refusal to accept meaninglessness. Yet, when we accept the absurd, we can engage with life passionately and defiantly, like Sisyphus pushing his boulder, turning suffering into a form of existential rebellion."),
                Perspective("Nihilism", " Nihilism holds that life lacks inherent meaning, purpose, or value, which can make suffering feel all the more oppressive. Without a framework of objective morality or cosmic justice, suffering can seem arbitrary and unbearable. Extreme nihilism may lead to despair, as no amount of effort can imbue life with lasting significance. However, some interpretations of nihilism suggest that recognising the emptiness of imposed meanings frees us from illusions that amplify suffering. Once we accept that suffering has no ultimate reason or lesson, we may encounter a kind of liberation from expectations and moral judgements. Suffering simply is—a fact of existence that neither condemns nor elevates life."),
                Perspective("Virtue Ethics", "Virtue Ethics, primarily drawn from Aristotle, sees suffering as both a challenge and a teacher in the cultivation of character. According to this view, the ultimate goal of life is eudaimonia—flourishing—which is achieved by living in accordance with virtue. Suffering arises from misfortune, vice, or ignorance, but it also offers an opportunity to develop virtues like courage, patience, and resilience. While pleasure and pain are not the primary measures of a good life, our responses to suffering determine our moral growth. By practicing the mean between extremes and using reason to guide action, we can transform suffering into a pathway for becoming a more virtuous and fulfilled individual."),
                Perspective("Buddhism", "Buddhism offers a profound and insightful perspective on the question, “Why do we suffer?” Central to its teachings is the concept of the Four Noble Truths, which form the foundation of understanding human suffering, known as dukkha. The first truth acknowledges that suffering is an unavoidable part of existence. Life is filled with moments of pain, dissatisfaction, and impermanence that affect all beings.The second truth explains that the root cause of suffering is craving, or tanha, which arises from attachment and desire. We suffer because we cling to things, people, and experiences, expecting them to remain permanent, even though the nature of life is constantly changing. Ignorance, or avidya, also plays a role, as it prevents us from seeing reality clearly..")
        )),
        LifeQuestion("Is success important?", "A successful life and a meaningful life are not necessarily the same thing.", listOf(
                Perspective("Stoicism", "Stoicism, founded by Zeno of Citium, holds that success in the conventional sense—wealth, fame, or authority—is neither inherently good nor truly important because it is beyond our full control. Stoic philosophy teaches that external circumstances are indifferent; what matters is how we respond to them with virtue and rationality. A Stoic views success as living in accordance with nature, where virtue is the only true good. Achieving inner tranquillity through self-discipline, acceptance of fate (amor fati), and mastering one’s desires is the essence of success. For example, a Stoic may lose their job yet remain peaceful and resilient, as their self-worth is rooted in moral character, not societal recognition. In this framework, success is redefined from achieving external goals to cultivating wisdom, courage, justice, and temperance. Epictetus and Marcus Aurelius embody this thinking, often stressing that we cannot control events, only our responses to them. Thus, while society’s definitions of success can be pursued without attachment, they are ultimately secondary to personal integrity and inner equanimity. True success for the Stoic is a harmonious life that neither pride nor misfortune can disturb.."),
                Perspective("Existentialism", "Existentialism, as explored by thinkers like Jean-Paul Sartre and Søren Kierkegaard, argues that life has no inherent meaning, and each individual must create their own purpose. Success, therefore, is important only in relation to one’s chosen values and authentic self-definition. An existentialist rejects universal or socially imposed standards of success, such as wealth or status, and instead focuses on whether one is living authentically. Authenticity means acknowledging the freedom and responsibility to define one’s own life path, even in the face of life’s absurdity and uncertainty. For example, a person may feel successful by dedicating themselves to art, teaching, or family life, even if society does not praise these choices. The existentialist sees success as a deeply personal and subjective construct, validated by the individual’s commitment to their own values rather than external approval. Failure to accept this responsibility can lead to bad faith, where one lives according to others’ expectations. Ultimately, success is important only to the extent it reflects a life lived with authenticity, courage, and self-awareness in a world devoid of predetermined meaning."),
                Perspective("Epicureanism", "Epicureanism, founded by Epicurus, redefines success as the attainment of a peaceful and pleasant life rather than the pursuit of wealth or power. For an Epicurean, success is important only insofar as it contributes to ataraxia (freedom from mental disturbance) and aponia (absence of physical pain). Grand ambitions and societal accolades often bring stress, competition, and anxiety, which conflict with the goal of inner peace. Instead, Epicurus advocates for a simple life composed of modest pleasures, close friendships, and philosophical reflection. In this perspective, success lies in avoiding unnecessary desires and fears—especially the fear of death—so one can enjoy the present moment. For example, an Epicurean might reject a high-paying but stressful corporate job in favour of a modest lifestyle that allows time for meaningful relationships and personal happiness. Success is not measured by productivity or social recognition but by the quiet joy of a well-balanced and self-sufficient life. Therefore, success is important, but only as a tool to achieve sustainable happiness and freedom from suffering, rather than as an end tied to social expectations."),
                Perspective("Utilitarianism", "Utilitarianism, popularised by Jeremy Bentham and John Stuart Mill, measures the importance of success based on its contribution to the greatest happiness of the greatest number. In this framework, success is not an isolated personal achievement but a moral concept tied to outcomes that maximise collective well-being. A successful life or action is one that increases overall happiness and reduces suffering, whether for oneself or for society at large. For a utilitarian, accumulating wealth or attaining fame is only meaningful if it leads to greater positive impact—such as philanthropy, social reform, or innovation that benefits others. For instance, a scientist might be considered truly successful not merely for professional recognition, but for developing a medical breakthrough that saves lives. Personal success is morally relevant only when its consequences contribute to the flourishing of others. Conversely, a life of self-serving achievement with no consideration for others’ happiness would not be commendable. Therefore, success is important in utilitarianism, but its value is instrumental—it matters because of its potential to generate the maximum net benefit for society as a whole.."),
                Perspective("Absurdism", "Absurdism, articulated by Albert Camus, highlights the tension between humanity’s desire for meaning and the universe’s indifference. Success, in this view, is ultimately absurd because no achievement can overcome life’s fundamental lack of inherent purpose. Yet, Camus encourages embracing life fully despite its absurdity, finding joy in the struggle itself. Success is neither inherently important nor meaningless—it gains significance only as a personal act of engagement and defiance against the void. For example, one might dedicate themselves to writing, teaching, or exploring the world, not because these pursuits fulfil a cosmic purpose, but because actively choosing them affirms one’s freedom. Success may be pursued, but without illusions of ultimate meaning or permanence. The story of Sisyphus illustrates this philosophy: even endlessly pushing a boulder uphill can be fulfilling if one embraces the act itself. Hence, success is important as a personal expression of will and vitality, rather than as a final answer to life’s existential questions.."),
                Perspective("Nihilism", "Nihilism, often associated with Friedrich Nietzsche’s critique of traditional values, argues that life lacks objective meaning, purpose, or intrinsic value. From a nihilistic standpoint, success is not inherently important because all human achievements are ultimately transient and cosmically insignificant. Wealth, fame, and personal accomplishments are social constructs that hold no universal truth or permanence. If nothing has inherent meaning, then success is only as relevant as the individual or society chooses to make it. Some nihilists may respond with despair, withdrawing from the pursuit of conventional success, while others may embrace a form of liberated indifference, creating their own temporary definitions of success. For example, a nihilist might view a prestigious career as ultimately meaningless in the grand scheme of time, yet still pursue hobbies or experiences for immediate enjoyment. In essence, success is not important in any objective sense; it is a human invention that dissolves when examined against the backdrop of an indifferent universe."),
                Perspective("Virtue Ethics", "Virtue Ethics, originating with Aristotle, sees success as important when it contributes to eudaimonia, or human flourishing. Rather than external rewards, true success lies in living a life of moral excellence by cultivating virtues such as courage, wisdom, justice, and temperance. Achievements in wealth, career, or status may be part of success, but only when they reflect and reinforce virtuous living. For instance, a business leader who gains recognition through honesty and social responsibility embodies success in a way that promotes both personal and communal well-being. Conversely, accomplishments attained through vice or harm to others cannot constitute true success. Virtue Ethics frames success as a holistic state of thriving in one’s personal, social, and moral dimensions. It is important because it reflects the fulfilment of human potential and the realisation of a character aligned with ethical principles. Success, therefore, is not merely instrumental or subjective—it represents the deep integration of external achievements with moral and personal excellence. ."),
                Perspective("Buddhism", "Buddhism teaches that attachment to worldly success often leads to suffering because all phenomena are impermanent. Chasing wealth, fame, or power fosters desire and clinging, which perpetuate dukkha (unsatisfactoriness). True success in Buddhism lies in breaking free from the cycle of craving and aversion, cultivating mindfulness, compassion, and wisdom. Achievements in the material world are not condemned, but they are recognised as transient and illusory in their ability to provide lasting happiness. A practitioner may engage with work or creative pursuits, but without attachment to the fruits of effort. Meditation, ethical conduct, and the Eightfold Path lead to the ultimate form of success: liberation from suffering and the attainment of Nirvana. For instance, a monk or layperson who lives with compassion, self-awareness, and equanimity is considered successful, regardless of social recognition. Success is important, but only in its spiritual sense, as progress towards inner freedom, peace, and awakening..")
        )),
        LifeQuestion("How do you know what is true?", "Our beliefs can feel obvious while still being wrong. Philosophy asks us to examine how we know.", listOf(
                Perspective("Stoicism", "Stoicism approaches the question of truth through the lens of rationality and alignment with nature. To the Stoic, truth is understood by cultivating reason, which they regard as a divine faculty present in every human being. They believe that the universe operates according to a rational, ordered structure, often referred to as the Logos, and by living in harmony with this law, one can discern truth. Truth is not dependent on external validation or shifting opinions but on the clarity of judgment that results from self-discipline and detachment from passions. Stoics encourage reflection, the examination of impressions, and the distinction between what is within our control and what is not. By critically observing our responses to events, we align ourselves with objective reality. Ultimately, truth for the Stoic is the recognition that our perceptions may be clouded by emotion and desire, and thus, understanding comes from steady reasoning and acceptance of the natural order."),
                Perspective("Existentialism", "Existentialism views the question of truth as deeply personal and subjective. Truth arises from individual experience and the choices one makes in a world without inherent meaning. Existentialist thinkers emphasise authenticity; to know what is true, one must confront the absurdity of life and accept responsibility for creating their own values. Truth is not an abstract, universal concept but rather the lived experience of engaging with one’s existence. Existentialists argue that societal norms, external authorities, or doctrines cannot provide ultimate truth because they often enforce conformity and suppress the individual’s freedom. Instead, truth resides in one’s honest confrontation with freedom, anxiety, and mortality. Through acts of self-definition, reflection, and authentic living, an individual arrives at truths that are meaningful to them, even if these truths cannot be universally demonstrated or accepted. For the existentialist, knowing what is true means embracing subjectivity and the ongoing process of defining oneself.."),
                Perspective("Epicureanism", "Epicureanism understands truth through the lens of sensory experience and rational reflection. Epicurus taught that the senses are the foundation of knowledge, as they provide the first impressions of reality. While senses can sometimes mislead, systematic reasoning allows us to interpret experiences correctly, discerning what is reliable and what is not. Truth, for the Epicurean, is tied to understanding the natural world and eliminating superstitious fears, particularly those of divine punishment or death. By studying nature and recognising that phenomena result from the movement of atoms in the void, one can distinguish truth from falsehood. Epicureans also emphasise practical truth, seeking knowledge that leads to ataraxia—peace of mind—by freeing oneself from irrational beliefs and unnecessary desires. For them, knowing what is true is not merely philosophical but directly linked to living a pleasurable and tranquil life. Clear reasoning, recognition of the evidence of the senses, and freedom from fear together illuminate the path to truth.."),
                Perspective("Utilitarianism", "Utilitarianism approaches truth pragmatically, linking it to outcomes and the greatest happiness principle. From a utilitarian perspective, knowing what is true often involves understanding cause and effect in human actions and their consequences for well-being. Truth, therefore, is evaluated by its capacity to produce beneficial results or prevent harm. This does not mean that utilitarianism disregards objective facts; rather, it emphasises that the meaningfulness of truth is revealed in its practical application to enhancing collective welfare. Philosophers like John Stuart Mill argue that truths are tested by their experiential verification and their ability to improve life quality. Scientific inquiry, empirical observation, and logical reasoning are essential tools in uncovering truths that guide moral decision-making. By assessing evidence and predicting the likely consequences of actions, one discerns which beliefs are justified and which are false. Ultimately, for the utilitarian, truth is bound to utility—the knowledge that leads to the greatest happiness for the greatest number.."),
                Perspective("Nihilism", "Nihilism takes a radical stance on truth, often questioning whether truth exists in any meaningful sense. From a nihilistic perspective, traditional claims to truth are human constructs, shaped by social, cultural, or psychological needs rather than any objective reality. Nihilists argue that attempts to define absolute truths are ultimately futile, as all systems of knowledge are contingent and limited. This perspective can lead to the conclusion that truth is either unknowable or irrelevant, leaving individuals to navigate a world devoid of inherent meaning or moral certainty. However, some strands of nihilism focus less on despair and more on liberation, seeing the rejection of imposed truths as an opportunity to act freely without illusion. In essence, knowing what is true for the nihilist involves recognising the void—acknowledging that all claims to ultimate truth may be baseless and that human understanding is always provisional. This confrontation with nothingness forms the core of nihilistic insight."),
                Perspective("Virtue Ethics", "Virtue ethics understands truth through the cultivation of character and practical wisdom (phronesis). For virtue ethicists, truth is not only an abstract correspondence with reality but also a lived quality that manifests in the actions of a virtuous person. Knowing what is true requires moral development and experiential learning, as the perception of truth is refined by habits of honesty, courage, and justice. Aristotle, a central figure in virtue ethics, argued that the virtuous person can perceive moral truths more clearly because their character aligns with reason and the good. Truth, in this context, is not static information but a dynamic understanding of what contributes to human flourishing (eudaimonia). By reflecting on real-life situations, practising self-awareness, and engaging in rational deliberation, a virtuous individual discerns what is genuinely true and good. Hence, in virtue ethics, the pursuit of truth is inseparable from the pursuit of moral excellence."),
                Perspective("Virtue Ethics", " Buddhism approaches the question of “How do you know what is true?” through a combination of direct experience, critical inquiry, and mindful observation. Unlike systems that rely solely on faith or authority, Buddhism encourages individuals to examine reality for themselves. The teachings of the Buddha, known as the Dharma, emphasise that truth is discovered through personal insight rather than blind acceptance. The Kalama Sutta offers valuable guidance in this regard. The Buddha advised the Kalamas not to accept something as true simply because it is heard frequently, taught by teachers, or recorded in scriptures. Instead, one should investigate through reason, reflection, and direct experience. If a belief or practice leads to the reduction of suffering, cultivates compassion, and fosters clarity of mind, it is more likely to be true and beneficial.")
        )),
        LifeQuestion("What should you do with your time?", "You cannot keep every possibility open forever. Choosing one life means leaving other possibilities behind.", listOf(
                Perspective("Existentialism", "Your finite time makes your choices significant. You are responsible for the life you choose.Existentialism holds that time is finite and inherently yours to define. There is no universal meaning or prescribed way to live, so what you do with your time must emerge from personal choice and authenticity. Existentialist thinkers like Sartre and Camus emphasise confronting the anxiety of existence and the responsibility of freedom. You are urged to reject societal scripts if they stifle your true self, and instead engage in actions that resonate with your own values and passions. The meaningful use of time comes from courageously facing the absurdity of life and creating meaning through your choices. To waste time is to live inauthentically, ignoring the call to define your own purpose."),
                Perspective("Epicureanism", "Value friendship, simple pleasures, and a peaceful life rather than endless accumulation.Epicureanism suggests that the best use of your time is to pursue lasting happiness by seeking pleasure and avoiding pain, but with wisdom and moderation. Epicurus taught that the greatest pleasures are simple: friendship, intellectual contemplation, and freedom from unnecessary desires. Time is best spent eliminating fears—especially of death and divine punishment—and cultivating a tranquil mind. Instead of chasing wealth, fame, or indulgence, an Epicurean spends time nurturing relationships, enjoying nature, and appreciating the present moment. The philosophy encourages a balance where activities bring sustainable joy and reduce anxiety. Properly used time leads to ataraxia, a state of peaceful contentment where life feels rich and fulfilling in its simplicity."),
                Perspective("Utilitarianism", "Utilitarianism judges the value of your time by its contribution to the greatest happiness for the greatest number. A utilitarian approach to time encourages using it to maximise well-being, reduce suffering, and create positive outcomes for others as well as yourself. Decisions about how to spend time are guided by calculating which actions bring the most overall benefit. Whether it is through work, charity, personal development, or innovation, your time should aim to increase net happiness in the world. Leisure and self-care are also justified, as they improve your capacity to contribute meaningfully. Misusing time would mean neglecting opportunities to make a positive difference or engaging in actions that cause harm or unnecessary suffering."),
                Perspective("Absurdism", "Absurdism, as expressed by Albert Camus, recognises the tension between humans seeking meaning and the universe’s apparent indifference. Time, therefore, should be spent embracing the absurd rather than being paralysed by it. The best use of your time is to live fully, to experience life in its raw authenticity, even without ultimate purpose. Camus would argue for passionate engagement—whether it is through creation, love, or rebellion against the absurdity—without expecting cosmic justification. Every moment becomes valuable when you acknowledge its fleetingness and choose to live it consciously. Wasting time comes from seeking rigid answers or surrendering to despair, rather than joyfully affirming the act of living despite life’s inherent lack of meaning."),
                Perspective("Nihilism", "Nihilism suggests that life has no intrinsic meaning, purpose, or objective value, which complicates the question of what to do with your time. A strict nihilist may see all actions as ultimately inconsequential, making any use of time equally arbitrary. However, this perspective can also be liberating, as it removes external pressures or moral imperatives. You may choose to spend your time however you wish—whether in indulgence, creativity, self-exploration, or even idleness—without fear of universal judgement. The risk lies in sliding into apathy or despair, where time feels empty. Yet, some embrace nihilism as a chance to define personal enjoyment or experience life for its own sake, accepting that nothing lasts beyond the present."),
                Perspective("Virtue Ethics", "Virtue ethics, inspired by Aristotle, teaches that time is best spent cultivating moral and intellectual virtues that lead to eudaimonia, or human flourishing. Every action you take contributes to the formation of your character, so conscious, deliberate use of time is crucial. Life should be an ongoing practice of developing habits like courage, generosity, patience, and honesty. Time is well used when it involves meaningful relationships, learning, and contribution to the community. Activities that align with your nature and allow you to express your best self are highly valued. From this perspective, wasting time is failing to nurture your character or neglecting opportunities for moral growth, which ultimately diminishes the quality of your life."),
                Perspective("Buddhism", "From a Buddhist perspective, the question of “What should you do with your life?” is approached through the lens of mindfulness, compassion, and the pursuit of liberation from suffering. The Buddha taught that life is impermanent and ever-changing, and clinging to desires or attachments often leads to dissatisfaction. Therefore, one should live with awareness, focusing on the present moment rather than being consumed by regrets of the past or anxieties about the future. The purpose of life, according to Buddhism, is to cultivate wisdom and compassion. By following the Noble Eightfold Path—right view, right intention, right speech, right action, right livelihood, right effort, right mindfulness, and right concentration—one can gradually free oneself from ignorance and craving. This does not necessarily mean renouncing the world entirely but engaging with it ethically and mindfully, ensuring that your actions contribute to the well-being of others as well as yourself.")
        )),
        LifeQuestion("What does it mean to live well?", "Perhaps living well is less about having the perfect life and more about becoming the kind of person you respect.", listOf(
                Perspective(" Stoicism", "For the Stoics, to live well is to achieve inner harmony by aligning with the rational order of nature. Life constantly presents events beyond our control, and suffering arises from clinging to these externals. Stoicism teaches that we cannot control external circumstances, but we can always control our judgments and responses. Central to living well is cultivating the four cardinal virtues: wisdom, courage, justice, and temperance. Wisdom allows us to discern what is within our power; courage helps us face adversity; justice guides our actions towards others; and temperance moderates our desires. A Stoic life is not about suppressing emotions entirely, but about understanding them and responding with reason. By practising negative visualisation, meditating on mortality, and detaching from fleeting pleasures or fears, one attains tranquillity, or apatheia. Living well thus means embracing fate (amor fati), accepting misfortune as a natural occurrence, and maintaining equanimity regardless of external fortune. For a Stoic, the highest good is virtue itself, and a life of moral excellence is inherently fulfilling. Material wealth, status, or pleasure are indifferent; they neither ensure happiness nor define a life well lived. True well-being arises from inner freedom, self-mastery, and harmony with the natural order of the cosmos."),
                Perspective("Existentialism", " Existentialism holds that life has no inherent or preordained meaning, and living well requires embracing this reality with courage and authenticity. Philosophers like Sartre, Kierkegaard, and Heidegger argue that individuals are “condemned to be free,” meaning that we bear the full weight of responsibility for our choices and cannot rely on divine or external authorities to define our purpose. Living authentically involves confronting existential anxiety instead of escaping into social conventions, distraction, or self-deception. To live well, one must actively create personal meaning through choices that reflect one’s true desires and values, even in a universe indifferent to human aspirations. This often entails accepting the absurdity of existence and continuing to act with commitment and passion despite it. Existentialists distinguish between authentic and inauthentic living: the former arises from self-determined action, while the latter stems from passive conformity. Living well is thus an ongoing process of self-creation, moral responsibility, and embracing freedom, even when it is uncomfortable. Happiness, in this view, is not the primary aim; rather, personal fulfilment comes from fully engaging with life, owning one’s decisions, and constructing meaning in the face of uncertainty and the inevitability of death."),
                Perspective("Epicureanism", "Epicureanism asserts that to live well is to pursue a life of pleasure, but pleasure is defined as the absence of pain (aponia) and mental disturbance (ataraxia), not indulgence in excess. Epicurus taught that most human suffering stems from unnecessary fears and uncontrolled desires—especially fear of death and fear of divine punishment. By understanding nature and the limits of desire, we can eliminate these fears and achieve contentment. Living well involves choosing simple, sustainable pleasures, cultivating deep friendships, reflecting on life through philosophical contemplation, and avoiding activities that lead to long-term pain or anxiety. Epicureans advocate the careful evaluation of desires: natural and necessary desires (like food and shelter) should be satisfied, whereas vain or unlimited desires (like wealth or fame) should be avoided. By prioritising mental over physical pleasures and living modestly, one experiences lasting happiness. For Epicurus, a good life is not lived in opulence but in tranquillity, with meaningful human connections and freedom from distress. Death, he argued, should not trouble us, for when we exist, death is not present, and when death arrives, we no longer exist. To live well is thus to be free, serene, and joyfully appreciative of life’s simple moments."),
                Perspective("Utilitarianism", "Utilitarianism teaches that living well involves maximising the overall happiness and well-being of all sentient beings. Rooted in the works of Jeremy Bentham and John Stuart Mill, utilitarian ethics evaluates every action by its consequences, with the moral aim of producing “the greatest happiness for the greatest number.” Living well, therefore, is not only a personal pursuit but a social responsibility. A good life is one where our decisions contribute positively to collective welfare, reducing suffering and increasing joy wherever possible. Utilitarianism distinguishes between higher and lower pleasures, with intellectual and moral satisfactions valued above mere physical gratification. To live well is to act as a responsible moral agent who considers the broader impact of one’s choices—how they affect family, community, society, and even future generations. In this way, personal fulfilment is interwoven with compassion and ethical calculation. Utilitarians see moral progress and social harmony as aligned with individual well-being. Living well does not necessarily mean selfless sacrifice; rather, it involves recognising that our own happiness is deeply connected to the happiness of others, and that a meaningful life emerges from maximising positive outcomes in the shared human experience."),
                Perspective("Absurdism", "Absurdism, as articulated by Albert Camus, posits that the human desire for meaning confronts a silent, indifferent universe, creating the “absurd.” Living well requires acknowledging life’s lack of inherent purpose without succumbing to despair or nihilism. Camus rejects both the resignation of nihilism and the leap of faith into religious or metaphysical systems as forms of evasion. Instead, he proposes revolt—consciously embracing life as it is, with all its contradictions. To live well is to engage fully in existence, to seek joy in the process of living rather than in ultimate answers. The “absurd hero,” like Sisyphus, finds meaning in the struggle itself, rolling his metaphorical boulder without expectation of lasting fulfilment. Absurdism encourages creativity, passion, and freedom, as we are liberated to shape our lives without the burden of ultimate justification. Living well thus involves relishing the beauty of existence, nurturing authentic experiences, and loving life despite its impermanence. By embracing the absurd rather than fleeing from it, we live with intensity, presence, and acceptance, transforming the lack of cosmic meaning into an invitation for personal liberation and profound appreciation of the here and now."),
                Perspective("Nihilism", "Nihilism asserts that life lacks inherent meaning, value, or moral structure. To live well under nihilism is to confront this void with honesty and determine how to exist in a world free of objective purpose. For some, this realisation leads to despair or apathy, but others see it as a form of liberation from imposed beliefs, dogmas, and societal expectations. Living well might involve embracing creative self-expression, constructing one’s own values, or pursuing experiences that bring personal satisfaction, however fleeting. Nietzsche, who explored nihilism extensively, warned against passive nihilism, which leads to resignation, and instead suggested an active response in which we create meaning through will and action. A nihilist life well lived does not seek external validation or cosmic justification; it is a life where authenticity prevails over illusion. The challenge is to harness the freedom that comes from meaninglessness as an opportunity rather than a void. By abandoning unfounded moral absolutes and embracing the subjective nature of existence, one can fashion a life of personal significance, however temporary. In this sense, to live well as a nihilist is to accept life’s emptiness and yet choose to engage with it fully and creatively."),
                Perspective("Virtue Ethics", "Virtue Ethics, founded in Aristotelian philosophy, teaches that living well means achieving eudaimonia, often translated as human flourishing or living in accordance with one’s highest potential. Unlike rule-based ethics, Virtue Ethics focuses on character development and the cultivation of moral and intellectual virtues. These include courage, temperance, justice, generosity, and practical wisdom (phronesis). A good life is a balanced life, where one consistently acts in harmony with reason and develops stable habits that reflect moral excellence. Virtue lies in finding the golden mean between extremes—for example, courage is the mean between recklessness and cowardice. Living well is not a momentary sensation but a lifelong practice of self-cultivation, reflection, and engagement with society. Relationships, community, and meaningful activity are essential, as humans are social beings whose flourishing depends on cooperation and shared values. Aristotle emphasised that happiness is an activity in accordance with virtue, not a passive state. To live well is to actualise one’s potential, contribute to the good of others, and maintain a harmonious, reflective life that emanates from a noble character.."),
                Perspective("Buddhism", "From a Buddhist perspective, to live well is to cultivate inner peace, wisdom, and compassion. Buddhism teaches that true well-being does not come from material possessions or fleeting pleasures but from a deep understanding of the nature of life and the mind. Central to this is the recognition of impermanence; everything is constantly changing, and clinging to temporary things leads to suffering. Living well involves following the Noble Eightfold Path, which guides ethical conduct, mental discipline, and the development of insight. By practising right speech, right action, and right livelihood, one nurtures harmony in personal and social life. Mindfulness and meditation help in observing one’s thoughts and emotions without attachment, leading to clarity and serenity..")
        ))
    )
    val philosophies = listOf(
        Philosophy("Stoicism", "Focus on what you can control.", "Stoicism teaches that peace comes from distinguishing your own judgments and actions from events you cannot control. Stoicism is an ancient philosophy that originated in Greece and later flourished in Rome. It teaches the development of self-control, rational thinking, and inner calm as a means to overcome destructive emotions and achieve a fulfilling life. Founded by Zeno of Citium in the early 3rd century BCE, Stoicism emphasises living in harmony with nature and accepting the things we cannot change. The core idea is that while we cannot always control external events, we can control our responses to them. Stoic thinkers, such as Seneca, Epictetus, and Marcus Aurelius, offered practical advice on how to cultivate resilience and virtue. They believed that true happiness lies in aligning our thoughts and actions with reason and moral character. Stoicism encourages detachment from fleeting pleasures and fears, focusing instead on inner strength and ethical living. teaches that true and lasting inner peace arises from a deep and sincere understanding of the difference between what is within our control and what lies beyond our influence. This ancient philosophy, shaped and refined by the wisdom of great thinkers like Epictetus, Marcus Aurelius, and Seneca, offers a timeless, practical, and resilient approach to facing the challenges of life. At its core, Stoicism rests upon a profound yet straightforward principle: our own mind, our judgments, the decisions we make, the actions we take, and the virtues we consciously choose to cultivate are entirely within our sphere of control."),
        Philosophy("Existentialism", "Create meaning through choice.", "Existentialism emphasizes freedom, responsibility, and the challenge of creating meaning in a world that may not provide it for you.Existentialism is a philosophical movement that explores the nature of human existence, freedom, and the meaning of life. It emphasises the individual as a free and responsible agent, capable of making choices that define their own essence, rather than adhering to pre-determined roles or societal expectations. The philosophy emerged prominently in the 19th and 20th centuries, with thinkers like Søren Kierkegaard, Friedrich Nietzsche, Jean-Paul Sartre, and Albert Camus contributing to its development. At its core, existentialism addresses the idea that life is inherently without predetermined meaning. This often leads to the concept of the absurd, a conflict between the human desire for purpose and the silent, indifferent universe. Existentialist thinkers argue that it is up to each person to create their own meaning through authentic choices and actions. Themes such as freedom, isolation, death, and personal responsibility are central to the existentialist approach."),
        Philosophy("Epicureanism", "A simple life can be a good life.", "Epicureanism values tranquility, friendship, modest pleasures, and freedom from unnecessary fear and desire.Epicureanism is a philosophical system founded by the Greek thinker Epicurus in the 4th century BCE. It is primarily concerned with the pursuit of happiness and the avoidance of pain through the cultivation of wisdom, moderation, and a tranquil state of mind. Contrary to popular belief, Epicureanism does not advocate indulgence in excessive pleasure. Instead, it emphasises simple living and the thoughtful selection of pleasures that lead to long-term contentment. At the core of Epicurean philosophy lies the concept of ataraxia, which refers to a state of inner tranquillity and freedom from mental disturbance. Epicurus taught that by understanding the nature of the world and the limits of human desires, one could achieve this state. This involves recognising that many of our anxieties stem from irrational fears, particularly fear of death and fear of the gods. Epicurean thought argues that death should not be feared as it is merely the end of sensation, and the gods, if they exist, are indifferent to human affairs.Epicureans also placed great importance on friendship as a source of happiness. They believed that social bonds and mutual support contribute significantly to a peaceful life. Additionally, they encouraged self-sufficiency and the cultivation of a modest lifestyle, free from the stresses of wealth and power. Epicurus’ ideas on the natural world were influenced by atomism—the belief that everything is composed of small, indivisible particles called atoms moving in the void. By understanding nature in this way, Epicureans sought to free people from superstitions and to promote a rational approach to life. Laws are interpretative, not clear about what qualifies and what doesn’t, in many cases."),
        Philosophy("Utilitarianism", "Consider the consequences.", "Utilitarianism evaluates actions partly by their consequences, especially how much overall well-being they produce.Utilitarianism is an ethical theory that asserts that the rightness or wrongness of actions is determined by their overall consequences, with the ultimate goal of maximising happiness or utility. Rooted in consequentialism, utilitarianism focuses not on the motives behind an action but on the outcome it produces. The central idea is often summarised as: the greatest happiness for the greatest number.Historical Background :The foundations of utilitarianism were laid in the 18th and 19th centuries by philosophers such as Jeremy Bentham and John Stuart Mill. Bentham proposed that all human actions are governed by the pursuit of pleasure and the avoidance of pain, and he developed the concept of the hedonic calculus to quantify happiness. Mill later refined the theory, distinguishing between higher and lower pleasures, and emphasising the quality of happiness over merely the quantity.Core Principle - Consequentialism: The morality of an action depends solely on its outcomes.Maximisation of Utility: The aim is to achieve the greatest overall well-being. Impartiality: Every individual’s happiness counts equally. Types of Utilitarianism Act Utilitarianism: Evaluates each action individually to determine its consequences for happiness.Rule Utilitarianism: Considers whether general adherence to a rule would maximise overall well-being. Strengths Utilitarianism provides a clear and pragmatic framework for decision-making. It can be applied to social policies, law-making, and moral dilemmas by prioritising actions that yield the most beneficial outcomes. Its emphasis on collective well-being aligns with the principles of democratic societies. Criticism : Despite its appeal, utilitarianism faces several criticisms: Quantifying happiness: Measuring and comparing happiness across individuals can be subjective and complex.Neglect of justice: The theory may justify morally questionable actions if they produce greater overall good.Demanding nature: It can require significant personal sacrifices to maximise collective happiness.Modern Applications Today, utilitarian reasoning is often used in public policy, healthcare allocation, environmental conservation, and technology ethics. Cost-benefit analyses and discussions on global issues like climate change frequently invoke utilitarian principles."),
        Philosophy("Nihilism", "Question whether meaning is objective.", "Nihilism challenges the idea that life necessarily contains objective meaning, value, or purpose.Nihilism is a philosophical doctrine that suggests the absence of intrinsic meaning, value, or purpose in life. It challenges the foundations of morality, knowledge, and societal norms, asserting that established beliefs are unfounded and life, in essence, is without ultimate significance. Origins and Historical ContextThe term nihilism is derived from the Latin word nihil, meaning nothing. Historically, it gained prominence in 19th-century Europe, particularly in Russia and Germany. Russian nihilism emerged as a socio-political movement rejecting traditional institutions, while German philosophers such as Friedrich Nietzsche explored the existential implications of a world devoid of divine or absolute truths. Philosophical Perspectives Metaphysical Nihilism: Suggests that physical objects may not exist in any substantial form, and reality itself could be an illusion.Moral Nihilism: Rejects objective moral values, implying that concepts of right and wrong are human constructs without universal grounding.Existential Nihilism: The most widely known type, asserting that life has no inherent purpose or meaning. Epistemological Nihilism: Questions the possibility of true knowledge, claiming that certainty is unattainable. Key Thinkers and Ideas Friedrich Nietzsche is often associated with nihilism, particularly through his declaration of the death of God. He argued that the decline of religious and metaphysical certainty leads to a confrontation with the void of meaning. However, Nietzsche also saw this as an opportunity to create new values through the concept of the Übermensch. Other philosophers, like Jean-Paul Sartre and Albert Camus, approached nihilism through existentialism. Camus, for instance, explored the absurd nature of life, emphasising the human struggle to find meaning in a purposeless universe. Cultural and Social ImplicationsNihilism has deeply influenced art, literature, and modern thought. It often manifests in themes of alienation, despair, and rebellion against traditional values. Modern literature, cinema, and music frequently reflect nihilistic perspectives, portraying characters or societies struggling with the void of meaning."),
        Philosophy("Absurdism", "Live despite the contradiction.", "Absurdism explores the tension between our desire for meaning and a universe that may not provide a final answer. Absurdism is a philosophical perspective that explores the conflict between human beings’ search for meaning and the apparent meaninglessness of the universe. This concept is rooted in the observation that humans naturally seek purpose, order, and understanding, yet the world often presents itself as chaotic, indifferent, and incomprehensible. The resulting tension is described as the “absurd.”The philosophy of absurdism is most closely associated with the French-Algerian writer Albert Camus, particularly through his essay The Myth of Sisyphus. Camus argued that while life may inherently lack meaning, the human desire to find meaning persists. The absurd arises from this contradiction. Unlike nihilism, which may reject the possibility of meaning entirely, absurdism acknowledges the absurd without necessarily advocating for despair.Camus presented three possible responses to the absurd: physical escape (such as suicide), philosophical escape (turning to belief systems or illusions of meaning), and acceptance. He rejected the first two and encouraged embracing the absurd, choosing to live fully and authentically despite the lack of inherent purpose. This approach is often referred to as “revolt,” where an individual continues to live, love, and create while accepting the universe’s indifference. In literature and art, absurdism often manifests as works that highlight the irrationality of life or depict characters struggling to find meaning in a senseless world. Playwrights like Samuel Beckett and Eugène Ionesco created absurdist theatre that uses humour, repetition, and illogical scenarios to reflect the human experience."),
        Philosophy("Virtue Ethics", "Become a good person.", "Virtue ethics focuses on character. Instead of asking only what action is correct, it asks what a good and flourishing person would do.Virtue ethics is a major branch of moral philosophy that focuses on the intrinsic qualities and moral character of individuals rather than merely assessing their external actions or the consequences of those actions. Rooted in the classical teachings of Aristotle and further shaped by the philosophical contributions of thinkers like Plato and Thomas Aquinas, virtue ethics proposes that genuine ethical behaviour arises from the cultivation of virtues such as honesty, courage, generosity, temperance, and wisdom. These virtues are not innate; they are nurtured over time through deliberate practice, self-reflection, and the formation of consistent habits, ultimately shaping one’s moral character. In contrast to deontological ethics, which upholds strict moral duties and rules as the foundation of ethical behaviour, or consequentialist theories like utilitarianism, which assess actions primarily based on their outcomes, virtue ethics asks a more fundamental question: “What kind of person should I be?” The focus is not simply on the moral evaluation of isolated actions but on the development of a well-rounded character that naturally inclines towards moral behaviour in diverse situations. A person who has cultivated virtues is seen as someone who will act ethically not out of obligation or fear of consequences but because their character aligns with goodness itself.The process of developing virtues involves a continuous journey of moral growth. It requires a conscious effort to engage in practices that foster positive traits, combined with the willingness to learn from daily experiences and moral challenges. For Aristotle, this development is closely tied to the concept of eudaimonia, often translated as human flourishing or living a fulfilled life. Achieving this state is not about momentary pleasure or external success but about living in harmony with one’s virtues and fulfilling one’s potential as a moral being. Practical wisdom, or phronesis, plays a central role in virtue ethics. It guides individuals in applying virtues appropriately to specific circumstances, balancing emotion and reason, and making choices that align with a virtuous life. For instance, courage as a virtue does not mean reckless bravery; it lies in striking the right balance between fear and overconfidence, determined by the context in which one acts. Similarly, generosity does not require giving away all possessions indiscriminately but involves thoughtful and meaningful acts of kindness where they are most needed."),
        Philosophy("Buddhism", "Understand suffering and attachment.", "Buddhist philosophy examines suffering, craving, impermanence, and the possibility of cultivating a less attached way of living. Buddhism is one of the world’s major religions and philosophical traditions, founded by Siddhartha Gautama, known as the Buddha, in the 5th–4th century BCE in ancient India. It is both a spiritual practice and a way of life, emphasising the path to enlightenment, inner peace, and liberation from the cycle of birth and rebirth, called samsara.The core teachings of Buddhism are encapsulated in the Four Noble Truths. The first truth acknowledges that life is filled with suffering (dukkha). The second truth identifies desire and attachment as the causes of suffering. The third truth states that overcoming desire leads to the cessation of suffering, known as nirvana. The fourth truth outlines the Noble Eightfold Path, a practical guide to achieve liberation, consisting of right view, right intention, right speech, right action, right livelihood, right effort, right mindfulness, and right concentration. Buddhism does not centre around the worship of a creator god but focuses on self-realisation, ethical living, and meditation. Meditation is a key practice, helping practitioners cultivate mindfulness, compassion, and wisdom. Ethical conduct, known as sila, is equally essential and involves refraining from harmful actions, speaking truthfully, and living responsibly.Over centuries, Buddhism spread beyond India to regions like Sri Lanka, Myanmar, Thailand, Tibet, China, Korea, and Japan, evolving into various schools such as Theravāda, Mahāyāna, and Vajrayāna. Theravāda, often considered the oldest school, emphasises individual liberation and strict adherence to the teachings of the Pali Canon. Mahāyāna Buddhism introduces the concept of the Bodhisattva, a being who aspires to attain enlightenment not just for oneself but for the benefit of all sentient beings. Vajrayāna, prominent in Tibet, incorporates esoteric practices, rituals, and tantric elements. Buddhist philosophy deeply explores the nature of reality. One of its central ideas is the concept of impermanence (anicca), teaching that all things are in constant flux. Another is non-self (anatta), which challenges the notion of a permanent, unchanging soul. These insights encourage detachment from ego and material attachments, fostering inner peace. In addition to personal practice, Buddhism has influenced art, architecture, literature, and culture across Asia. Magnificent stupas, intricate mandalas, and serene statues of the Buddha reflect the spiritual ideals of clarity and tranquillity. Buddhist festivals like Vesak, which commemorates the birth, enlightenment, and passing away of the Buddha, are celebrated with devotion and joy.")
    )
    val advice = listOf(
        AdviceItem("Control what you can.", "Your attention is limited. Spend more of it on your choices and less on events you cannot command."),
        AdviceItem("Question your assumptions.", "A belief feeling obvious does not make it true. Ask what you are assuming and why."),
        AdviceItem("Don't confuse popularity with value.", "Something being admired by many people does not automatically make it worthwhile."),
        AdviceItem("Choose your values deliberately.", "If you never examine your values, you may simply inherit them from everyone around you."),
        AdviceItem("Make room for uncertainty.", "You do not need perfect certainty to think carefully or make a reasonable decision."),
        AdviceItem("Remember that time is finite.", "You cannot do everything. What you repeatedly choose to spend time on becomes part of your life."),
        AdviceItem("Learn to change your mind.", "Changing your position after finding better reasons is not weakness. It is intellectual honesty.")
    )
}

private enum class MainTab(val label: String) {
    Home("Home"), Questions("Questions"), Philosophies("Philosophies"), Advice("Advice")
}

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContent { PhilosophiaApp() }
    }
}

@Composable
private fun PhilosophiaApp() {
    var selectedTab by remember { mutableStateOf(MainTab.Home) }
    var selectedQuestion by remember { mutableStateOf<LifeQuestion?>(null) }
    var selectedPhilosophy by remember { mutableStateOf<Philosophy?>(null) }

    BackHandler(enabled = selectedQuestion != null || selectedPhilosophy != null) {
        selectedQuestion = null
        selectedPhilosophy = null
    }

    val darkColors = darkColorScheme(
        primary = Slate,
        onPrimary = NearBlack,
        background = NearBlack,
        surface = Graphite,
        onSurface = Color(0xFFF1F1F3),
        secondary = Color(0xFFB7C0CA)
    )

    MaterialTheme(colorScheme = darkColors) {
        Scaffold(
            containerColor = NearBlack,
            bottomBar = {
                if (selectedQuestion == null && selectedPhilosophy == null) {
                    NavigationBar(containerColor = Color(0xFF15171D)) {
                        MainTab.values().forEach { tab ->
                            val icon = when (tab) {
                                MainTab.Home -> Icons.Outlined.Home
                                MainTab.Questions -> Icons.Outlined.QuestionAnswer
                                MainTab.Philosophies -> Icons.Outlined.Book
                                MainTab.Advice -> Icons.Outlined.Lightbulb
                            }
                            NavigationBarItem(
                                selected = selectedTab == tab,
                                onClick = { selectedTab = tab },
                                icon = { Icon(icon, contentDescription = tab.label) },
                                label = { Text(tab.label, fontSize = 10.sp) },
                                colors = NavigationBarItemDefaults.colors(
                                    selectedIconColor = Slate,
                                    selectedTextColor = Slate,
                                    indicatorColor = Color(0xFF343A45),
                                    unselectedIconColor = Color(0xFF9299A3),
                                    unselectedTextColor = Color(0xFF9299A3)
                                )
                            )
                        }
                    }
                }
            }
        ) { innerPadding ->
            Box(
                modifier = Modifier
                    .fillMaxSize()
                    .background(BackgroundBrush)
                    .padding(innerPadding)
            ) {
                when {
                    selectedQuestion != null -> DetailScaffold(
                        title = "Question",
                        onBack = { selectedQuestion = null }
                    ) { QuestionDetail(selectedQuestion!!) }
                    selectedPhilosophy != null -> DetailScaffold(
                        title = selectedPhilosophy!!.name,
                        onBack = { selectedPhilosophy = null }
                    ) { PhilosophyDetail(selectedPhilosophy!!) }
                    else -> when (selectedTab) {
                        MainTab.Home -> HomeScreen(onBrowse = { selectedTab = MainTab.Questions })
                        MainTab.Questions -> QuestionsScreen(onSelect = { selectedQuestion = it })
                        MainTab.Philosophies -> PhilosophiesScreen(onSelect = { selectedPhilosophy = it })
                        MainTab.Advice -> AdviceScreen()
                    }
                }
            }
        }
    }
}

@Composable
private fun DetailScaffold(title: String, onBack: () -> Unit, content: @Composable () -> Unit) {
    Column(Modifier.fillMaxSize()) {
        Row(
            Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 12.dp),
            verticalAlignment = Alignment.CenterVertically
        ) {
            IconButton(onClick = onBack) {
                Icon(Icons.Outlined.ArrowBack, contentDescription = "Back", tint = Slate)
            }
            Text(title, color = Color.White, fontWeight = FontWeight.SemiBold, fontSize = 18.sp)
        }
        content()
    }
}

@Composable
private fun HomeScreen(onBrowse: () -> Unit) {
    Column(
        Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(20.dp),
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        Spacer(Modifier.height(18.dp))
        Text("PHILOSOPHIA", color = Color(0xFFB0B6C0), fontSize = 12.sp, fontWeight = FontWeight.Bold, letterSpacing = 3.sp)
        Spacer(Modifier.height(12.dp))
        Text(
            "The Fever of Philosophy",
            color = Color.White,
            fontSize = 36.sp,
            lineHeight = 42.sp,
            fontWeight = FontWeight.Bold,
            textAlign = TextAlign.Center
        )
        Spacer(Modifier.height(8.dp))
        Text("A Place For Big Questions.", color = Color(0xFFB7BEC8), fontSize = 18.sp, textAlign = TextAlign.Center)
        Spacer(Modifier.height(24.dp))
        HorizontalDivider(color = Color.White.copy(alpha = 0.10f))
        Spacer(Modifier.height(22.dp))
        Text("Start with a question.", color = Color.White, fontSize = 23.sp, fontWeight = FontWeight.Bold)
        Spacer(Modifier.height(14.dp))
        Button(
            onClick = onBrowse,
            colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF3A414D), contentColor = Color.White),
            shape = RoundedCornerShape(14.dp)
        ) { Text("Browse Questions", modifier = Modifier.padding(horizontal = 8.dp, vertical = 3.dp)) }
        Spacer(Modifier.height(28.dp))
        ContentCard {
            Text("What is philosophy?", color = Color.White, fontSize = 21.sp, fontWeight = FontWeight.Bold)
            Spacer(Modifier.height(8.dp))
            Text(
                "Philosophy is the practice of examining the questions beneath ordinary life: what is true, what matters, how we should live, and what we can know.",
                color = Color(0xFFC0C5CD), lineHeight = 24.sp
            )
        }
        Spacer(Modifier.height(18.dp))
        ContentCard {
            Text("“The unexamined life is not worth living.”", color = Color.White, fontSize = 20.sp, fontStyle = FontStyle.Italic, lineHeight = 28.sp)
            Spacer(Modifier.height(10.dp))
            Text("— Socrates, as portrayed by Plato", color = Color(0xFFADB5C0), fontSize = 13.sp)
        }
        Spacer(Modifier.height(20.dp))
    }
}

@Composable
private fun QuestionsScreen(onSelect: (LifeQuestion) -> Unit) {
    Column(Modifier.fillMaxSize()) {
        ScreenHeading("Life Questions")
        LazyColumn(contentPadding = PaddingValues(start = 16.dp, end = 16.dp, bottom = 20.dp), verticalArrangement = Arrangement.spacedBy(12.dp)) {
            items(PhilosophiaData.questions) { q ->
                ContentCard(Modifier.fillMaxWidth().clickable { onSelect(q) }) {
                    Text(q.question, color = Color.White, fontSize = 18.sp, fontWeight = FontWeight.SemiBold)
                    Spacer(Modifier.height(6.dp))
                    Text(q.reflection, color = Color(0xFFB9C0CA), fontSize = 14.sp, lineHeight = 20.sp, maxLines = 3)
                }
            }
        }
    }
}

@Composable
private fun QuestionDetail(question: LifeQuestion) {
    Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(horizontal = 18.dp, vertical = 8.dp)) {
        Text(question.question, color = Color.White, fontSize = 31.sp, lineHeight = 38.sp, fontWeight = FontWeight.Bold)
        Spacer(Modifier.height(16.dp))
        Text(question.reflection, color = Color(0xFFC1C7D0), fontSize = 18.sp, lineHeight = 27.sp)
        Spacer(Modifier.height(22.dp))
        HorizontalDivider(color = Color.White.copy(alpha = 0.12f))
        Spacer(Modifier.height(18.dp))
        Text("Perspectives", color = Color.White, fontSize = 23.sp, fontWeight = FontWeight.Bold)
        Spacer(Modifier.height(14.dp))
        question.perspectives.forEach { perspective ->
            ContentCard(Modifier.fillMaxWidth()) {
                Text(perspective.name, color = Color.White, fontSize = 18.sp, fontWeight = FontWeight.SemiBold)
                Spacer(Modifier.height(8.dp))
                if (perspective.name == "Nihilism") {
                    Image(
                        painter = painterResource(id = R.drawable.nihilism_image),
                        contentDescription = "Nihilism illustration",
                        modifier = Modifier.fillMaxWidth().heightIn(max = 180.dp).clip(RoundedCornerShape(12.dp))
                    )
                    Spacer(Modifier.height(8.dp))
                }
                Text(perspective.text, color = Color(0xFFC0C5CD), lineHeight = 22.sp)
            }
            Spacer(Modifier.height(12.dp))
        }
        Text("There may not be one final answer. The point is to think carefully.", color = Color(0xFF9FA8B4), fontSize = 13.sp, modifier = Modifier.padding(vertical = 12.dp))
    }
}

@Composable
private fun PhilosophiesScreen(onSelect: (Philosophy) -> Unit) {
    Column(Modifier.fillMaxSize()) {
        ScreenHeading("Life Questions")
        LazyColumn(contentPadding = PaddingValues(16.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
            items(PhilosophiaData.philosophies) { p ->
                ContentCard(Modifier.fillMaxWidth().clickable { onSelect(p) }) {
                    Text(p.name, color = Color.White, fontSize = 18.sp, fontWeight = FontWeight.SemiBold)
                    Spacer(Modifier.height(5.dp))
                    Text(p.subtitle, color = Color(0xFFB8C0CA), fontSize = 14.sp)
                }
            }
        }
    }
}

@Composable
private fun PhilosophyDetail(philosophy: Philosophy) {
    Column(Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(18.dp)) {
        ContentCard(Modifier.fillMaxWidth()) {
            Text(philosophy.name, color = Color.White, fontSize = 29.sp, fontWeight = FontWeight.Bold, lineHeight = 35.sp)
            Spacer(Modifier.height(14.dp))
            Text(philosophy.explanation, color = Color(0xFFC0C5CD), lineHeight = 23.sp)
        }
    }
}

@Composable
private fun AdviceScreen() {
    Column(Modifier.fillMaxSize()) {
        ScreenHeading("A Few Pieces of Advice")
        LazyColumn(contentPadding = PaddingValues(16.dp), verticalArrangement = Arrangement.spacedBy(14.dp)) {
            items(PhilosophiaData.advice) { item ->
                ContentCard(Modifier.fillMaxWidth()) {
                    Text(item.title, color = Color.White, fontSize = 18.sp, fontWeight = FontWeight.SemiBold)
                    Spacer(Modifier.height(8.dp))
                    Text(item.text, color = Color(0xFFC0C5CD), lineHeight = 22.sp)
                }
            }
        }
    }
}

@Composable
private fun ScreenHeading(title: String) {
    Text(title, color = Color.White, fontSize = 24.sp, fontWeight = FontWeight.Bold, modifier = Modifier.padding(horizontal = 18.dp, vertical = 18.dp))
}

@Composable
private fun ContentCard(modifier: Modifier = Modifier, content: @Composable ColumnScope.() -> Unit) {
    Card(
        modifier = modifier,
        shape = RoundedCornerShape(16.dp),
        colors = CardDefaults.cardColors(containerColor = CardColor.copy(alpha = 0.88f)),
        elevation = CardDefaults.cardElevation(defaultElevation = 5.dp)
    ) {
        Column(Modifier.fillMaxWidth().padding(16.dp), content = content)
    }
}
